// Catalog accuracy gate: src/catalog.json is generated by
// scripts/build-catalog.mjs from scripts/data/data.json, and these tests fail
// when the two stop agreeing. Nothing here edits either file; defaults are
// mainnet values.
import { describe, expect, it } from 'vitest';

import catalogJson from '../../src/catalog.json';
import seedRaw from '../../scripts/data/data.json?raw';
import fixtureJson from '../../scripts/data/reference-defaults.json';
import { KINDS, TIERS, validateCatalog } from '../../src/catalog.schema';
import type { Catalog, Kind, SectionDef, SettingDef } from '../../src/catalog.schema';
import type { ConfigValue } from '../../src/config/types';

const catalog: Catalog = validateCatalog(catalogJson);
const sections: SectionDef[] = Object.values(catalog.sections);
const settings: SettingDef[] = sections.flatMap((section) => Object.values(section.settings));
const fixture = fixtureJson as Record<string, Record<string, ConfigValue>>;

// The three views are built on this mix, so a change to it is a design change,
// not a data refresh.
const EXPECTED_TIER_COUNTS: Record<string, number> = {
  essential: 10,
  service: 8,
  advanced: 1,
  table: 24,
};

const EXPECTED_KIND_COUNTS: Record<Kind, number> = {
  boolean: 80,
  integer: 256,
  decimal: 8,
  text: 36,
  path: 30,
  list: 51,
  enum: 1,
};

const SERVICE_SECTIONS = 8;
const TABLE_SECTIONS = 24;

// bs derives these bucket counts from each table's expected count and the
// installed memory. The shipped numbers are one machine's, not defaults.
const DERIVED_SETTINGS = [
  'table.header.buckets',
  'table.ins.buckets',
  'table.outs.buckets',
  'table.pool.buckets',
  'table.strong.buckets',
  'table.tx.buckets',
  'table.wtxid.buckets',
];

/** "section.key" -> definition; settings nest under their section. */
function settingAt (where: string): SettingDef | undefined {
  const index = where.lastIndexOf('.');
  return catalog.sections[where.slice(0, index)]?.settings[where.slice(index + 1)];
}

function flaggedWhere (): string[] {
  return sections
    .flatMap((section) =>
      Object.values(section.settings)
        .filter((setting) => setting.derived === true)
        .map((setting) => `${section.key}.${setting.key}`),
    )
    .sort();
}

async function sha256Hex (text: string): Promise<string> {
  const bytes = new TextEncoder().encode(text);
  const digest = await crypto.subtle.digest('SHA-256', bytes);
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, '0')).join('');
}

/** The default is of the type its kind promises. The schema enforces this; so does the count below. */
function defaultMatchesKind (kind: Kind, value: ConfigValue): boolean {
  switch (kind) {
    case 'boolean':
      return typeof value === 'boolean';
    case 'integer':
      return typeof value === 'number' && Number.isInteger(value);
    case 'decimal':
      return typeof value === 'number';
    case 'text':
    case 'path':
    case 'enum':
      return typeof value === 'string';
    case 'list':
      return Array.isArray(value) && value.every((element) => typeof element === 'string');
  }
}

function countBy<T extends string> (values: T[]): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const value of values) counts[value] = (counts[value] ?? 0) + 1;
  return counts;
}

describe('catalog meta', () => {
  it('declares the 43 sections and 462 settings it actually carries', () => {
    expect(catalog.meta.sectionCount).toBe(43);
    expect(catalog.meta.settingCount).toBe(462);
    expect(sections).toHaveLength(43);
    expect(settings).toHaveLength(462);
  });

  it('targets bs v4 and carries a defaults tree per network', () => {
    expect(catalog.meta.version).toBe('v4');
    expect(catalog.meta.defaultsScope).toBe('network');
  });

  it('stamps the sha256 of the seed it was generated from', async () => {
    const digest = await sha256Hex(seedRaw);
    expect(digest).toMatch(/^[0-9a-f]{64}$/);
    expect(catalog.meta.seedSha256).toBe(digest);
  });
});

describe('catalog validation', () => {
  it('accepts the shipped catalog', () => {
    expect(() => validateCatalog(catalogJson)).not.toThrow();
  });

  it('rejects a setting with no help string', () => {
    const broken = JSON.parse(JSON.stringify(catalogJson)) as {
      sections: Record<string, { settings: Record<string, { help?: string }> }>;
    };
    delete broken.sections.log.settings.path.help;
    expect(() => validateCatalog(broken)).toThrow();
  });

  it('rejects a default whose type contradicts its kind', () => {
    const broken = JSON.parse(JSON.stringify(catalogJson)) as {
      sections: Record<string, { settings: Record<string, { default: unknown }> }>;
    };
    broken.sections.log.settings.path.default = 7;
    expect(() => validateCatalog(broken)).toThrow();
  });

  it('carries no UI-only __ section or setting key', () => {
    for (const section of sections) {
      expect(section.key.startsWith('__'), `section ${section.key}`).toBe(false);
      for (const setting of Object.values(section.settings)) {
        expect(setting.key.startsWith('__'), `setting ${section.key}.${setting.key}`).toBe(false);
      }
    }
  });
});

describe('sections', () => {
  it('has the tier mix the navigation is built on', () => {
    expect(countBy(sections.map((section) => section.tier))).toEqual(EXPECTED_TIER_COUNTS);
  });

  it('marks every service section with service=true and enableKey bind', () => {
    const serviceSections = sections.filter((section) => section.service);
    expect(serviceSections).toHaveLength(SERVICE_SECTIONS);

    for (const section of sections) {
      if (section.tier === 'service') {
        expect(section.service, `${section.key} is a service`).toBe(true);
      }
      if (section.service) {
        expect(section.tier, `${section.key} tier`).toBe('service');
        expect(section.enableKey, `${section.key} enableKey`).toBe('bind');
        expect(section.settings.bind, `${section.key} has a bind setting`).toBeDefined();
      }
    }
  });

  it('makes every table section a fixed-at-creation table', () => {
    const tableSections = sections.filter((section) => section.key.startsWith('table.'));
    expect(tableSections).toHaveLength(TABLE_SECTIONS);

    for (const section of sections) {
      if (section.key.startsWith('table.')) {
        expect(section.tier, `${section.key} tier`).toBe('table');
        expect(section.fixedAtCreation, `${section.key} fixedAtCreation`).toBe(true);
      }
      if (section.tier === 'table') {
        expect(section.key.startsWith('table.'), `${section.key} is a table section`).toBe(true);
      }
    }
  });
});

describe('settings', () => {
  it('names and explains every setting', () => {
    for (const section of sections) {
      for (const setting of Object.values(section.settings)) {
        const where = `${section.key}.${setting.key}`;
        expect(setting.key.trim().length > 0, `${where} key`).toBe(true);
        expect(setting.label.trim().length > 0, `${where} label`).toBe(true);
        expect(setting.help.trim().length > 0, `${where} help`).toBe(true);
        expect(TIERS, `${where} tier`).toContain(setting.tier);
        expect(KINDS, `${where} kind`).toContain(setting.kind);
      }
    }
  });

  it('gives every setting a default of its kind, with the expected kind counts', () => {
    const matching = settings.filter((setting) => defaultMatchesKind(setting.kind, setting.default));
    expect(matching).toHaveLength(462);
    expect(countBy(settings.map((setting) => setting.kind))).toEqual(EXPECTED_KIND_COUNTS);
  });

  it('keeps numeric bounds sane where both ends are given', () => {
    for (const section of sections) {
      for (const setting of Object.values(section.settings)) {
        if (setting.min !== undefined && setting.max !== undefined) {
          expect(setting.min, `${section.key}.${setting.key} min <= max`).toBeLessThanOrEqual(
            setting.max
          );
        }
      }
    }
  });

  it('describes every value of every enum', () => {
    const enums = settings.filter((setting) => setting.kind === 'enum');
    expect(enums).toHaveLength(1);

    for (const setting of enums) {
      expect(setting.values, `${setting.key} values`).toBeDefined();
      expect(setting.valueHelp, `${setting.key} valueHelp`).toBeDefined();

      const values = setting.values ?? [];
      const valueHelp = setting.valueHelp ?? {};
      expect(values.length > 0, `${setting.key} has values`).toBe(true);
      expect(Object.keys(valueHelp).sort(), `${setting.key} valueHelp covers every value`).toEqual(
        values.map((value) => value.value).sort()
      );
      for (const value of values) {
        expect(valueHelp[value.value], `${setting.key} valueHelp[${value.value}]`).toBeTruthy();
      }
      expect(values.some((value) => value.value === setting.default), `${setting.key} default`).toBe(
        true
      );
    }
  });
});

describe('derived settings', () => {
  it('flags exactly the seven derived bucket counts', () => {
    expect(flaggedWhere()).toEqual(DERIVED_SETTINGS);
  });

  it('gives the flag to no other setting', () => {
    for (const section of sections) {
      for (const setting of Object.values(section.settings)) {
        if (DERIVED_SETTINGS.includes(`${section.key}.${setting.key}`)) continue;
        expect(setting.derived, `${section.key}.${setting.key} is not derived`).toBeUndefined();
      }
    }
  });

  it('keeps the flag independent of fixedAtCreation', () => {
    // A table bucket that bs takes literally is fixed at creation, and is not derived.
    const literal = settingAt('table.duplicate.buckets');
    expect(literal?.fixedAtCreation).toBe(true);
    expect(literal?.derived).toBeUndefined();

    for (const where of DERIVED_SETTINGS) {
      expect(settingAt(where), where).toBeDefined();
      expect(settingAt(where)?.kind, where).toBe('integer');
    }
  });

  it('says how the strong table gets its bucket count', () => {
    expect(settingAt('table.strong.buckets')?.help).toContain('derived from tx expected');
  });
});

describe('accuracy gate', () => {
  it('has a fixture entry for every catalog setting, and no extras', () => {
    for (const section of sections) {
      expect(fixture[section.key], `fixture section ${section.key}`).toBeDefined();
      for (const key of Object.keys(section.settings)) {
        expect(fixture[section.key]?.[key], `fixture ${section.key}.${key}`).toBeDefined();
      }
    }
    for (const [sectionKey, values] of Object.entries(fixture)) {
      const section = catalog.sections[sectionKey];
      expect(section, `fixture section ${sectionKey} is in the catalog`).toBeDefined();
      if (!section) continue;
      for (const key of Object.keys(values)) {
        expect(section.settings[key], `fixture ${sectionKey}.${key} is in the catalog`).toBeDefined();
      }
    }
  });

  it('matches the reference defaults element by element', () => {
    for (const section of sections) {
      for (const setting of Object.values(section.settings)) {
        const where = `${section.key}.${setting.key}`;
        const expected = fixture[section.key][setting.key];

        if (Array.isArray(expected)) {
          expect(Array.isArray(setting.default), `${where} is a list`).toBe(true);
          const actual = setting.default as string[];
          expect(actual.length, `${where} list length`).toBe(expected.length);
          expected.forEach((element, index) => {
            expect(actual[index], `${where}[${index}]`).toEqual(element);
          });
        } else {
          expect(Array.isArray(setting.default), `${where} is a scalar`).toBe(false);
          expect(setting.default, `${where} default`).toEqual(expected);
        }
      }
    }
  });
});

describe('verification record', () => {
  it('names the build the settings were checked against', () => {
    const { version, date, serverCommit } = catalog.meta.verifiedAgainst;

    expect(version).toMatch(/^\d+\.\d+\.\d+$/);
    expect(date).toMatch(/^\d{4}-\d{2}-\d{2}$/);
    expect(serverCommit).toMatch(/^[0-9a-f]{7,40}$/);
  });
});
